const FORMAS_PAGO = ['efectivo', 'tarjeta', 'bizum'];

const texto = (v) => String(v ?? '').replace(/[\u00a0\s]+/g, ' ').trim();
const sinTildes = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const clave = (v) => sinTildes(texto(v)).toLowerCase();

function leerCsv(contenido) {
  const t = String(contenido ?? '').replace(/^\uFEFF/, '');
  const registros = [];
  let fila = [], campo = '', comillas = false;
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (comillas) {
      if (c === '"' && t[i + 1] === '"') { campo += '"'; i++; }
      else if (c === '"') comillas = false;
      else campo += c;
    } else if (c === '"') comillas = true;
    else if (c === ',') { fila.push(campo); campo = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && t[i + 1] === '\n') i++;
      fila.push(campo); registros.push(fila); fila = []; campo = '';
    } else campo += c;
  }
  if (campo !== '' || fila.length) { fila.push(campo); registros.push(fila); }
  const cabecera = (registros.shift() || []).map(clave);
  return registros
    .map((r, i) => ({ fila: i + 2, valores: Object.fromEntries(cabecera.map((h, j) => [h, r[j] ?? ''])) }))
    .filter((r) => Object.values(r.valores).some((v) => texto(v) !== ''));
}

// dia/mes/anio; el anio de dos cifras es 2000 + aa
function normalizarFecha(valor) {
  const m = texto(valor).match(/^(\d{1,2})\/(\d{1,2})\/(\d{2}|\d{4})$/);
  if (!m) return null;
  const d = +m[1], mes = +m[2], a = m[3].length === 2 ? 2000 + +m[3] : +m[3];
  const f = new Date(Date.UTC(a, mes - 1, d));
  if (f.getUTCFullYear() !== a || f.getUTCMonth() !== mes - 1 || f.getUTCDate() !== d) return null;
  return `${a}-${String(mes).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

// devuelve centimos enteros o null; sin parseFloat
function normalizarImporte(valor) {
  let s = texto(valor).replace(/€/g, '').replace(/\s/g, '');
  if (!/^\d[\d.,]*$/.test(s)) return null;
  const puntos = (s.match(/\./g) || []).length, comas = (s.match(/,/g) || []).length;
  if (puntos && comas) {
    if (s.lastIndexOf(',') < s.lastIndexOf('.') || comas > 1) return null;
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (comas) {
    if (comas > 1 || !/^\d+,\d{1,2}$/.test(s)) return null;
    s = s.replace(',', '.');
  } else if (puntos && !/^\d+\.\d{1,2}$/.test(s)) return null;
  const [ent, dec = ''] = s.split('.');
  return parseInt(ent, 10) * 100 + parseInt((dec + '00').slice(0, 2), 10);
}

function normalizarFormaPago(valor) {
  const f = clave(valor);
  if (!f) return { valor: null, incidencia: 'forma_pago_ausente' };
  if (FORMAS_PAGO.includes(f)) return { valor: f, incidencia: null };
  return { valor: null, incidencia: 'forma_pago_no_reconocida' };
}

function normalizarFilaApartado({ fila, valores: v }) {
  const r = { archivo: 'apartados', fila, clave: `migracion:apartados:${fila}`, ignorada_como: null, incidencias: [], datos: null };
  if (/^total/i.test(texto(v.fecha))) { r.ignorada_como = 'total_manual'; return r; }
  const fecha = normalizarFecha(v.fecha);
  const precio = normalizarImporte(v.precio);
  const abono = normalizarImporte(v.abono);
  if (!fecha) r.incidencias.push('fecha_invalida');
  if (precio === null || precio <= 0) r.incidencias.push('precio_invalido');
  if (abono === null || abono <= 0) r.incidencias.push('abono_invalido');
  const fp = normalizarFormaPago(v.forma_pago); // el CSV de apartados no trae esta columna
  if (fp.incidencia) r.incidencias.push(fp.incidencia);
  r.datos = {
    fecha, cliente: texto(v.cliente), cliente_clave: clave(v.cliente),
    telefono: texto(v.telefono).replace(/\D/g, ''),
    producto: texto(v.modelo), producto_clave: clave(v.modelo), talla: texto(v.talla),
    precio_cent: precio, abono_cent: abono,
    precio: precio === null ? null : precio / 100, abono: abono === null ? null : abono / 100,
    forma_pago: fp.valor, notas: texto(v.notas),
  };
  return r;
}

function normalizarFilaVenta({ fila, valores: v }) {
  const r = { archivo: 'ventas', fila, clave: `migracion:ventas:${fila}`, ignorada_como: null, incidencias: [], datos: null };
  if (/^total/i.test(texto(v.fecha))) { r.ignorada_como = 'total_manual'; return r; }
  const fecha = normalizarFecha(v.fecha);
  const importe = normalizarImporte(v.importe);
  if (!fecha) r.incidencias.push('fecha_invalida');
  if (importe === null || importe <= 0) r.incidencias.push('importe_invalido');
  const fp = normalizarFormaPago(v.forma_pago);
  if (fp.incidencia) r.incidencias.push(fp.incidencia);
  r.datos = { fecha, concepto: texto(v.concepto), concepto_clave: clave(v.concepto),
    importe_cent: importe, importe: importe === null ? null : importe / 100, forma_pago: fp.valor };
  return r;
}

const body = $input.first().json.body ?? {};
return [{ json: {
  modo: body.modo === 'carga' ? 'carga' : 'analisis',
  autorizada: body.autorizada === true,
  apartados: leerCsv(body.csv_apartados).map(normalizarFilaApartado),
  ventas: leerCsv(body.csv_ventas).map(normalizarFilaVenta),
} }];

const MINIMO_INICIAL_CENT = 500;
const PLAZO_DIAS = 90;

const sumarDias = (iso, dias) => {
  const d = new Date(`${iso}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + dias);
  return d.toISOString().slice(0, 10);
};
const euros = (cent) => cent / 100;

function agrupar({ apartados, ventas }) {
  const ignoradas = [];
  const validas = [];
  for (const r of apartados) {
    if (r.ignorada_como) ignoradas.push({ archivo: r.archivo, fila: r.fila, clave: r.clave, ignorada_como: r.ignorada_como });
    else validas.push(r);
  }

  // telefonos compartidos por nombres distintos: identidad dudosa
  const nombresPorTelefono = new Map();
  for (const r of validas) {
    const t = r.datos.telefono;
    if (!t) continue;
    if (!nombresPorTelefono.has(t)) nombresPorTelefono.set(t, new Set());
    nombresPorTelefono.get(t).add(r.datos.cliente_clave);
  }

  // un apartado = mismo cliente, producto y talla
  const porGrupo = new Map();
  for (const r of validas) {
    const d = r.datos;
    const id = `${d.cliente_clave}|${d.producto_clave}|${d.talla}`;
    if (!porGrupo.has(id)) porGrupo.set(id, []);
    porGrupo.get(id).push(r);
  }

  const ventasValidas = ventas.filter((v) => {
    if (v.ignorada_como) { ignoradas.push({ archivo: v.archivo, fila: v.fila, clave: v.clave, ignorada_como: v.ignorada_como }); return false; }
    return true;
  });
  const ventaUsada = new Map(); // fila de venta -> clave del pago

  const grupos = [];
  for (const [id, filas] of porGrupo) {
    filas.sort((a, b) => (a.datos.fecha || '').localeCompare(b.datos.fecha || '') || a.fila - b.fila);
    const [ini, ...resto] = filas;
    const d = ini.datos;
    const motivos = new Set();
    const avisos = new Set();

    for (const f of filas) for (const c of f.incidencias) if (c !== 'forma_pago_ausente') motivos.add(c);
    if (new Set(filas.map((f) => f.datos.telefono).filter(Boolean)).size > 1) motivos.add('identidad_dudosa_telefonos_distintos');
    if ([...nombresPorTelefono.get(d.telefono) || []].length > 1) motivos.add('identidad_dudosa_telefono_compartido');
    if (!filas.some((f) => f.datos.telefono)) avisos.add('sin_telefono_contacto_no_verificable');
    if (new Set(filas.map((f) => f.datos.precio_cent)).size > 1) motivos.add('precio_inconsistente');
    if (d.abono_cent !== null && d.abono_cent < MINIMO_INICIAL_CENT) motivos.add('abono_inicial_menor_que_5');
    if (d.abono_cent !== null && d.precio_cent !== null && d.abono_cent > d.precio_cent) motivos.add('abono_inicial_mayor_que_precio');
    const total = filas.reduce((s, f) => s + (f.datos.abono_cent || 0), 0);
    if (d.precio_cent !== null && total > d.precio_cent) motivos.add('pagos_superan_precio');
    if (d.fecha && resto.some((f) => f.datos.fecha > sumarDias(d.fecha, PLAZO_DIAS))) motivos.add('abono_fuera_de_plazo');
    const retenida = motivos.size > 0;

    // pagos: el primero es el inicial; los demas son abonos posteriores
    const pagos = filas.map((f, i) => {
      const pago = { rol: i === 0 ? 'inicial' : 'abono', fila: f.fila, clave: f.clave, fecha: f.datos.fecha,
        importe_cent: f.datos.abono_cent, forma_pago: f.datos.forma_pago, fuente_forma_pago: f.datos.forma_pago ? 'csv_apartados' : null, venta_fila: null };
      if (!pago.forma_pago) {
        const c = ventasValidas.filter((v) => !ventaUsada.has(v.fila) && !v.incidencias.includes('fecha_invalida') &&
          v.datos.fecha === pago.fecha && v.datos.importe_cent === pago.importe_cent &&
          (v.datos.concepto_clave.includes(d.cliente_clave) || (d.producto_clave && v.datos.concepto_clave.includes(d.producto_clave))));
        if (c.length === 1) {
          ventaUsada.set(c[0].fila, pago.clave);
          pago.venta_fila = c[0].fila;
          if (c[0].datos.forma_pago) { pago.forma_pago = c[0].datos.forma_pago; pago.fuente_forma_pago = `ventas:fila-${c[0].fila}`; }
        } else if (c.length > 1) avisos.add(`venta_ambigua_fila_${pago.fila}`);
      }
      return pago;
    });
    if (pagos.some((p) => !p.forma_pago)) motivos.add('forma_pago_ausente');

    grupos.push({
      id, cliente: d.cliente, telefono: d.telefono, producto: d.producto, talla: d.talla, precio_cent: d.precio_cent,
      estado: retenida ? 'retenida' : motivos.size ? 'en_revision' : 'lista',
      hold_related_rows: retenida, motivos: [...motivos], avisos: [...avisos],
      normalizado: { fecha: d.fecha, precio: euros(d.precio_cent), abono_inicial: euros(d.abono_cent) },
      pagos,
    });
  }

  // ventas: pago de apartado, revision o venta real
  const pagoDeApartado = [], ventasRevision = [], ventasReales = [];
  for (const v of ventasValidas) {
    if (ventaUsada.has(v.fila)) { pagoDeApartado.push({ fila: v.fila, clave: v.clave, pago_clave: ventaUsada.get(v.fila) }); continue; }
    const motivos = [...v.incidencias];
    if (/\b(abono|apartado)\b/.test(v.datos.concepto_clave)) motivos.push('venta_parece_abono_sin_apartado');
    if (motivos.length) ventasRevision.push({ fila: v.fila, clave: v.clave, motivos });
    else ventasReales.push(v);
  }

  // plan de carga: solo apartados listos y ventas reales
  const plan = [];
  for (const g of grupos.filter((x) => x.estado === 'lista')) {
    const [ini, ...abonos] = g.pagos;
    const payload = { cliente: g.cliente, producto: g.producto, precio: euros(g.precio_cent),
      abono_inicial: euros(ini.importe_cent), forma_pago: ini.forma_pago, fecha: ini.fecha };
    if (g.telefono) payload.telefono = g.telefono;
    if (g.talla) payload.talla = g.talla;
    plan.push({ tipo: 'apartado', clave: ini.clave, grupo: g.id, payload });
    for (const a of abonos) plan.push({ tipo: 'abono', clave: a.clave, grupo: g.id, apartado_clave: ini.clave,
      payload: { importe: euros(a.importe_cent), forma_pago: a.forma_pago, fecha: a.fecha } });
  }
  for (const v of ventasReales) plan.push({ tipo: 'venta', clave: v.clave,
    payload: { concepto: v.datos.concepto, importe: euros(v.datos.importe_cent), forma_pago: v.datos.forma_pago, fecha: v.datos.fecha } });

  const cuenta = (e) => grupos.filter((g) => g.estado === e).length;
  return {
    grupos, ventas_pago_de_apartado: pagoDeApartado, ventas_revision: ventasRevision, ignoradas, plan_carga: plan,
    resumen: { grupos: grupos.length, listas: cuenta('lista'), en_revision: cuenta('en_revision'), retenidas: cuenta('retenida'),
      ventas_reales: ventasReales.length, ventas_pago_de_apartado: pagoDeApartado.length, ventas_revision: ventasRevision.length,
      ignoradas: ignoradas.length, post_count: plan.length },
  };
}

const entrada = $input.first().json;
return [{ json: { modo: entrada.modo, autorizada: entrada.autorizada, ...agrupar(entrada) } }];

const MOTIVOS = {
  forma_pago_ausente: 'falta la forma de pago de algún pago',
  forma_pago_no_reconocida: 'forma de pago no reconocida',
  abono_inicial_menor_que_5: 'abono inicial menor de 5 €',
  abono_inicial_mayor_que_precio: 'abono inicial mayor que el precio',
  pagos_superan_precio: 'los pagos superan el precio',
  abono_fuera_de_plazo: 'abono posterior a los 90 días',
  precio_inconsistente: 'precio distinto entre filas',
  identidad_dudosa_telefonos_distintos: 'mismo nombre con teléfonos distintos',
  identidad_dudosa_telefono_compartido: 'teléfono compartido por clientes distintos',
  fecha_invalida: 'fecha no válida',
  precio_invalido: 'precio no válido',
  abono_invalido: 'abono no válido',
  importe_invalido: 'importe no válido',
  venta_parece_abono_sin_apartado: 'parece un abono pero no se encuentra su apartado',
  sin_telefono_contacto_no_verificable: 'sin teléfono: enlazado solo por nombre, producto y talla',
};
const txt = (c) => MOTIVOS[c] || (c.startsWith('venta_ambigua_fila_') ? `varias ventas encajan con el pago de la fila ${c.split('_').pop()}` : c);
const eur = (cent) => `${(cent / 100).toFixed(2).replace('.', ',')} €`;
const filas = (g) => `${g.pagos.length > 1 ? 'filas' : 'fila'} ${g.pagos.map((p) => p.fila).join(', ')}`;
const dia = (iso) => iso ? iso.split('-').reverse().join('/') : 'sin fecha';
const pagoTxt = (p) => `${p.rol} ${eur(p.importe_cent)} el ${dia(p.fecha)} (${p.forma_pago || 'forma de pago desconocida'}${p.venta_fila ? `, según ventas fila ${p.venta_fila}` : ''})`;

function redactar(a, config) {
  const r = a.resumen;
  const bloqueGrupo = (g) => [
    `- ${g.cliente} · ${g.producto} T${g.talla} · ${eur(g.precio_cent)} · ${filas(g)}`,
    ...g.pagos.map((p) => `    ${pagoTxt(p)}`),
    ...g.motivos.map((m) => `    Motivo: ${txt(m)}`),
    ...g.avisos.map((m) => `    Aviso: ${txt(m)}`),
  ];
  const seccion = (titulo, lineas) => lineas.length ? ['', titulo, ...lineas] : [];
  const listas = a.grupos.filter((g) => g.estado === 'lista');
  const revision = a.grupos.filter((g) => g.estado === 'en_revision');
  const retenidas = a.grupos.filter((g) => g.estado === 'retenida');
  const ventasPlan = a.plan_carga.filter((o) => o.tipo === 'venta');

  const lineas = [
    'Hola Marisa:',
    '',
    'Este es el análisis del Excel antiguo. No se ha escrito nada en la tienda.',
    '',
    'Resumen',
    `- Apartados encontrados: ${r.grupos} (listos ${r.listas}, en revisión ${r.en_revision}, retenidos ${r.retenidas})`,
    `- Ventas reales: ${r.ventas_reales}`,
    `- Filas de ventas que son pagos de apartados: ${r.ventas_pago_de_apartado}`,
    `- Filas ignoradas: ${r.ignoradas}`,
    `- Operaciones que se cargarían: ${r.post_count}`,
    ...seccion('Necesitan tu decisión (no se cargan)', revision.flatMap(bloqueGrupo)),
    ...seccion('Retenidos con todas sus filas (no se cargan)', retenidas.flatMap(bloqueGrupo)),
    ...seccion('Ventas que necesitan revisión', a.ventas_revision.map((v) => `- Ventas fila ${v.fila}: ${v.motivos.map(txt).join('; ')}`)),
    ...seccion('Plan de carga: apartados', listas.flatMap(bloqueGrupo)),
    ...seccion('Plan de carga: ventas', ventasPlan.map((o) => `- ${dia(o.payload.fecha)} · ${o.payload.concepto} · ${eur(Math.round(o.payload.importe * 100))} · ${o.payload.forma_pago} (fila ${o.clave.split(':')[2]})`)),
    ...seccion('Pagos de apartados que estaban en el libro de ventas (no se cargan como venta)', a.ventas_pago_de_apartado.map((v) => `- Ventas fila ${v.fila} → apartados fila ${v.pago_clave.split(':')[2]}`)),
    ...seccion('Ignoradas', a.ignoradas.map((i) => `- ${i.archivo} fila ${i.fila}: ${i.ignorada_como === 'total_manual' ? 'total escrito a mano' : i.ignorada_como}`)),
    '',
    'La carga solo se hará cuando confirmes este plan. Las filas en revisión se cargarán cuando indiques la forma de pago o la corrección.',
  ];
  return {
    destinatario: config.CORREO_MARISA,
    remitente: config.CORREO_REMITENTE,
    asunto: `Paso Firme · Migración del Excel: ${r.post_count} operaciones listas, ${r.en_revision + r.retenidas} apartados por revisar`,
    texto: lineas.join('\n'),
  };
}

const { config, entrada } = $input.first().json;
return [{ json: { ...entrada, documento: redactar(entrada, config) } }];

const { config, entrada } = $input.first().json;
const RUTAS = { apartado: '/api/apartados', venta: '/api/ventas', abono: '' };
return entrada.plan_carga.map((o) => ({ json: {
  clave: o.clave,
  apartado_clave: o.apartado_clave || '',
  documento: { tipo_operacion: o.tipo, ruta: RUTAS[o.tipo], grupo: o.grupo || null, payload: o.payload },
} }));

const { config, entrada } = $('Leer configuración').first().json;
const plan = Object.fromEntries(entrada.plan_carga.map((o) => [o.clave, o]));
const filas = $input.all().map((i) => i.json).filter((r) => r.clave);
const eur = (n) => `${Number(n).toFixed(2).replace('.', ',')} €`;
const describir = (clave) => {
  const o = plan[clave] || {}; const p = o.payload || {}; const fila = clave.split(':').slice(1).join(' fila ');
  if (o.tipo === 'apartado') return `${fila}: apartado de ${p.cliente} · ${p.producto} · inicial ${eur(p.abono_inicial)}`;
  if (o.tipo === 'abono') return `${fila}: abono de ${eur(p.importe)} del ${p.fecha.split('-').reverse().join('/')}`;
  if (o.tipo === 'venta') return `${fila}: venta ${p.concepto} · ${eur(p.importe)}`;
  return fila;
};
const de = (cond) => filas.filter(cond);
const creadas = de((r) => r.estado === 'confirmado' && r.en_esta_ejecucion);
const yaEstaban = de((r) => r.estado === 'confirmado' && !r.en_esta_ejecucion);
const revision = de((r) => r.estado === 'revision');
const pendientes = de((r) => r.estado === 'reservado');
const sinReservar = de((r) => r.estado === 'sin_reservar');
const seccion = (titulo, lista, extra = () => '') => lista.length ? ['', `${titulo} (${lista.length})`, ...lista.map((r) => `- ${describir(r.clave)}${extra(r)}`)] : [];
const fuera = entrada.resumen.en_revision + entrada.resumen.retenidas;
const lineas = [
  'Hola Marisa:',
  '',
  'Resultado de la carga del Excel antiguo que autorizaste.',
  ...seccion('Creadas ahora', creadas),
  ...seccion('Ya estaban cargadas (no se repiten)', yaEstaban),
  ...seccion('En revisión: la tienda no confirmó la operación, no se reintenta', revision, (r) => r.error ? `\n    Respuesta: ${r.error}` : ''),
  ...seccion('Pendientes de conciliar: reservadas sin confirmación, comprobar en la tienda', pendientes),
  ...seccion('Sin cargar: su apartado no está confirmado', sinReservar),
  '',
  `Quedan fuera de esta carga ${fuera} apartados en revisión o retenidos, según el informe de análisis.`,
];
return [{ json: { documento: {
  destinatario: config.CORREO_MARISA,
  remitente: config.CORREO_REMITENTE,
  asunto: `Paso Firme · Carga de la migración: ${creadas.length} creadas, ${yaEstaban.length} ya estaban, ${revision.length + pendientes.length + sinReservar.length} por revisar`,
  texto: lineas.join('\n'),
}, resumen_carga: { creadas: creadas.length, ya_estaban: yaEstaban.length, revision: revision.length, pendientes: pendientes.length, sin_reservar: sinReservar.length } } }];
